mapper.select:
SELECT DATE(so.order_date) as report_date, COUNT(DISTINCT so.id) as order_count, SUM(soi.quantity) as total_quantity, SUM(soi.amount) as total_amount, SUM(soi.quantity * COALESCE(i.cost_price, 0)) as total_cost, SUM(soi.amount) - SUM(soi.quantity * COALESCE(i.cost_price, 0)) as gross_profit, CASE WHEN SUM(soi.amount) > 0 THEN (SUM(soi.amount) - SUM(soi.quantity * COALESCE(i.cost_price, 0))) / SUM(soi.amount) * 100 ELSE 0 END as profit_rate FROM sales_order so INNER JOIN sales_order_item soi ON so.id = soi.order_id LEFT JOIN inventory i ON soi.product_id = i.product_id AND so.warehouse_id = i.warehouse_id WHERE so.status = 1
AND so.order_date >= #{startDate}
AND so.order_date <= #{endDate}
AND so.warehouse_id = #{warehouseId}
GROUP BY DATE(so.order_date) ORDER BY report_date DESC

SELECT DATE_FORMAT(so.order_date, '%Y-%m') as report_date, COUNT(DISTINCT so.id) as order_count, SUM(soi.quantity) as total_quantity, SUM(soi.amount) as total_amount, SUM(soi.quantity * COALESCE(i.cost_price, 0)) as total_cost, SUM(soi.amount) - SUM(soi.quantity * COALESCE(i.cost_price, 0)) as gross_profit, CASE WHEN SUM(soi.amount) > 0 THEN (SUM(soi.amount) - SUM(soi.quantity * COALESCE(i.cost_price, 0))) / SUM(soi.amount) * 100 ELSE 0 END as profit_rate FROM sales_order so INNER JOIN sales_order_item soi ON so.id = soi.order_id LEFT JOIN inventory i ON soi.product_id = i.product_id AND so.warehouse_id = i.warehouse_id WHERE so.status = 1
AND so.order_date >= #{startDate}
AND so.order_date <= #{endDate}
AND so.warehouse_id = #{warehouseId}
GROUP BY DATE_FORMAT(so.order_date, '%Y-%m') ORDER BY report_date DESC

SELECT ROW_NUMBER() OVER (ORDER BY SUM(soi.amount) DESC) as prodRank, p.sku_code, p.product_name, p.spec, SUM(soi.quantity) as total_quantity, SUM(soi.amount) as total_amount FROM sales_order so INNER JOIN sales_order_item soi ON so.id = soi.order_id INNER JOIN product p ON soi.product_id = p.id WHERE so.status = 1
AND so.order_date >= #{startDate}
AND so.order_date <= #{endDate}
AND so.warehouse_id = #{warehouseId}
GROUP BY p.id, p.sku_code, p.product_name, p.spec ORDER BY total_amount DESC LIMIT #{limit}

SELECT ROW_NUMBER() OVER (ORDER BY SUM(soi.amount) DESC) as custRank, c.customer_name, COUNT(DISTINCT so.id) as order_count, SUM(soi.amount) as total_amount FROM sales_order so INNER JOIN sales_order_item soi ON so.id = soi.order_id INNER JOIN customer c ON so.customer_id = c.id WHERE so.status = 1
AND so.order_date >= #{startDate}
AND so.order_date <= #{endDate}
AND so.warehouse_id = #{warehouseId}
GROUP BY c.id, c.customer_name ORDER BY total_amount DESC LIMIT #{limit}

SELECT p.sku_code, p.product_name, p.spec, i.quantity, i.cost_price, (i.quantity * i.cost_price) as stock_amount, COALESCE(sales30.sales_qty, 0) as sales_30d, CASE WHEN COALESCE(sales30.sales_qty, 0) > 0 THEN ROUND(i.quantity / (COALESCE(sales30.sales_qty, 0) / 30.0), 1) ELSE 999 END as turnover_days, CASE WHEN COALESCE(sales30.sales_qty, 0) = 0 AND i.quantity > 0 THEN '滞销' WHEN i.quantity <= COALESCE(p.min_stock, 0) THEN '补货' WHEN COALESCE(sales30.sales_qty, 0) > 0 AND i.quantity / (COALESCE(sales30.sales_qty, 0) / 30.0) < 7 THEN '快周转' ELSE '正常' END as health_status FROM inventory i INNER JOIN product p ON i.product_id = p.id LEFT JOIN ( SELECT soi.product_id, so.warehouse_id, SUM(soi.quantity) as sales_qty FROM sales_order so INNER JOIN sales_order_item soi ON so.id = soi.order_id WHERE so.status = 1 AND so.order_date >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) GROUP BY soi.product_id, so.warehouse_id ) sales30 ON i.product_id = sales30.product_id AND i.warehouse_id = sales30.warehouse_id
WHERE i.warehouse_id = #{warehouseId}
ORDER BY turnover_days ASC
